[
  {
    "name": "read",
    "description": "读取工作区内文件内容；可用 start_line/end_line 读取指定行区间（大文件分片阅读）",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "相对工作区根的路径"
        },
        "start_line": {
          "type": "number",
          "description": "起始行号（从 1 起，可选）"
        },
        "end_line": {
          "type": "number",
          "description": "结束行号（含，可选）"
        }
      },
      "required": [
        "path"
      ]
    }
  }
]
